edits.oldText:
browserController?._isTrackVisible = (String path) {
  if (path.isEmpty) return false;
  // `scrollCacheExtent: 0` + hard clip means a mounted row implies it is
  // within the visible region.
  final rowContext = rowKeys[path]?.currentContext;
  if (rowContext == null) return false;
  final box = rowContext.findRenderObject();
  return box is RenderBox && box.hasSize;
};

edits.newText:
browserController?._isTrackVisible = (String path) {
  if (path.isEmpty) return false;
  // `scrollCacheExtent: 0` + hard clip means a mounted row implies it is
  // within the visible region.
  final rowContext = rowKeys[path]?.currentContext;
  if (rowContext == null) return false;
  // Widget tests can query during rebuilds where the element is
  // temporarily inactive; guard against `findRenderObject()` assertions.
  if (rowContext is Element && !rowContext.mounted) return false;
  try {
    final box = rowContext.findRenderObject();
    return box is RenderBox && box.hasSize;
  } catch (_) {
    return false;
  }
};

